files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --snake: #0f9b8e;
  --food: #e94560;
  --grid: #0f3460;
  --btn-bg: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-active: #0a2647;
  --focus: #e94560;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  max-width: 480px;
  width: 100%;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 8px;
  background: var(--grid);
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.85);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.overlay-content h2 {
  font-size: 1.5rem;
  color: var(--accent);
}

.overlay-content p {
  font-size: 1rem;
  line-height: 1.5;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid transparent;
  border-radius: 8px;
  background: var(--btn-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 100px;
}

.btn:hover:not(:disabled) {
  background: var(--btn-hover);
}

.btn:active:not(:disabled) {
  background: var(--btn-active);
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover:not(:disabled) {
  background: #f05a75;
}

.btn.primary:active:not(:disabled) {
  background: #c73550;
}

.instructions {
  font-size: 0.9rem;
  color: #9aa5b1;
  text-align: center;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 80px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayHint = document.getElementById('overlayHint');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;

  let snake = [];
  let food = { x: 0, y: 0 };
  let direction = { x: 1, y: 0 };
  let nextDirection = { x: 1, y: 0 };
  let score = 0;
  let gameState = 'paused'; // 'paused', 'running', 'gameover'
  let gameLoop = null;
  let speed = 150;

  function resetGame() {
    snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    speed = 150;
    scoreEl.textContent = '0';
    placeFood();
    draw();
  }

  function placeFood() {
    let valid = false;
    while (!valid) {
      food = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      valid = !snake.some(seg => seg.x === food.x && seg.y === food.y);
    }
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(
      food.x * CELL_SIZE + 1,
      food.y * CELL_SIZE + 1,
      CELL_SIZE - 2,
      CELL_SIZE - 2
    );

    // Draw snake
    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#0f9b8e' : '#0b7a70';
      ctx.fillRect(
        seg.x * CELL_SIZE + 1,
        seg.y * CELL_SIZE + 1,
        CELL_SIZE - 2,
        CELL_SIZE - 2
      );
    });
  }

  function update() {
    direction = { ...nextDirection };
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Wall collision
    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      endGame();
      return;
    }

    // Self collision
    if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
      if (speed > 60) {
        speed = Math.max(60, speed - 5);
        restartLoop();
      }
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameState = 'gameover';
    clearInterval(gameLoop);
    gameLoop = null;
    overlayTitle.textContent = 'Game Over';
    overlayText.textContent = 'Your final score is ' + score + '.';
    overlayHint.textContent = 'Press Restart or Space to play again.';
    overlay.hidden = false;
    startBtn.disabled = true;
    pauseBtn.disabled = true;
    pauseBtn.textContent = 'Pause';
    restartBtn.focus();
  }

  function startGame() {
    if (gameState === 'running') return;
    resetGame();
    gameState = 'running';
    overlay.hidden = true;
    startBtn.disabled = true;
    pauseBtn.disabled = false;
    pauseBtn.textContent = 'Pause';
    startLoop();
    canvas.focus();
  }

  function togglePause() {
    if (gameState === 'running') {
      gameState = 'paused';
      clearInterval(gameLoop);
      gameLoop = null;
      pauseBtn.textContent = 'Resume';
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Game is paused. Press Space or Resume to continue.';
      overlayHint.textContent = '';
      overlay.hidden = false;
    } else if (gameState === 'paused') {
      gameState = 'running';
      pauseBtn.textContent = 'Pause';
      overlay.hidden = true;
      startLoop();
    }
  }

  function startLoop() {
    if (gameLoop) clearInterval(gameLoop);
    gameLoop = setInterval(update, speed);
  }

  function restartLoop() {
    if (gameState === 'running') {
      startLoop();
    }
  }

  function restartGame() {
    clearInterval(gameLoop);
    gameLoop = null;
    gameState = 'paused';
    resetGame();
    overlayTitle.textContent = 'How to Play';
    overlayText.textContent = 'Use arrow keys to move. Eat the red food to grow and increase your score. Avoid hitting walls or yourself.';
    overlayHint.innerHTML = 'Press <strong>Space</strong> or click <strong>Start</strong> to begin.';
    overlay.hidden = false;
    startBtn.disabled = false;
    pauseBtn.disabled = true;
    pauseBtn.textContent = 'Pause';
    startBtn.focus();
  }

  function handleKey(e) {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }

    if (key === ' ') {
      if (gameState === 'gameover') {
        restartGame();
      } else if (gameState === 'paused') {
        if (startBtn.disabled) {
          togglePause();
        } else {
          startGame();
        }
      } else if (gameState === 'running') {
        togglePause();
      }
      return;
    }

    if (gameState !== 'running') return;

    if (key === 'ArrowUp' && direction.y === 0) {
      nextDirection = { x: 0, y: -1 };
    } else if (key === 'ArrowDown' && direction.y === 0) {
      nextDirection = { x: 0, y: 1 };
    } else if (key === 'ArrowLeft' && direction.x === 0) {
      nextDirection = { x: -1, y: 0 };
    } else if (key === 'ArrowRight' && direction.x === 0) {
      nextDirection = { x: 1, y: 0 };
    }
  }

  // Event listeners
  document.addEventListener('keydown', handleKey);
  startBtn.addEventListener('click', startGame);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restartGame);

  // Initial state: start paused with instructions
  resetGame();
  overlay.hidden = false;
  startBtn.disabled = false;
  pauseBtn.disabled = true;
})();
